## Refactored Code Snippet

Below is a **sample improved `app.js`** incorporating the fixes above. Use as a reference or copy‑paste after installing the required dependencies (`helmet`, `cors`, `express-rate-limit`) via `npm install helmet cors express-rate-limit`.

```js
// app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// --- 1. Create application instance ---------------------------------
const app = express();

// --- 2. Basic security middleware ------------------------------------
app.enable('trust proxy');            // Trust X-Forwarded-* from a reverse proxy
app.use(helmet());                    // Sets common security headers
app.use(helmet.contentSecurityPolicy({   // MITM-friendly CSP
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    upgradeInsecureRequests: [],
  }
}));
app.use(helmet.hsts({ maxAge: 31536000 })); // Strict-Transport-Security

// --- 3. CORS ----------------------------------------------------------
app.use(cors({
  origins: ['https://example.com'],   // replace with your domain(s)
  methods: ['GET', 'POST', 'OPTIONS'],
}));

// --- 4. Body parsing -------------------------------------------------
app.use(express.json());

// --- 5. Rate limiting -------------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 200,                // limit each IP to 200 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', limiter);  // Apply to specific endpoint

// --- 6. Routes --------------------------------------------------------
app.get('/health', (req, res) => {
  // Reduce exposure of timestamp precision
  const now = new Date();
  res.json({
    status: 'ok',
    timestamp: now.toISOString().split('T')[0] + 'T' + now.toTimeString().split(' ')[0]
  });
});

app.get('/users', (req, res) => {
  // In a real app, authenticate the request here
  // TODO: Replace with DB call, add pagination & filtering
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' }
  ]);
});

// --- 7. 404 and Generic Error Handlers -------------------------------
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not Found' });
});
app.use((err, req, res, next) => {
  // eslint-disable-next-line no-console
  console.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});

// --- 8. Start ---------------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  // eslint-disable-next-line no-console
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

