## 3. Concrete Recommendations & Code Examples

### 3.1 Install & use Helmet (security headers)

```bash
npm i helmet
```

```js
// at the top, right after express import
const helmet = require('helmet');

const app = express();
app.use(helmet());          // Sets many headers

// Optional CSP tweaking
app.use(
  helmet.contentSecurityPolicy({
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"], // adjust based on real usage
    },
  })
);
```

### 3.2 Enforce HTTPS (redirect HTTP → HTTPS)

```bash
# use a reverse proxy (Nginx) or run behind it
# or in code using a middleware

app.enable('trust proxy');  // if behind reverse proxy

app.use((req, res, next) => {
  if (!req.secure && req.get('X-Forwarded-Proto') !== 'https') {
    return res.redirect('https://' + req.get('host') + req.originalUrl);
  }
  next();
});
```

### 3.3 Add CORS policy (only allow known domains)

```bash
npm i cors
```

```js
const cors = require('cors');

const corsOptions = {
  origin: ['https://example.com', 'https://app.example.com'], // whitelist
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));
```

### 3.4 Basic authentication on `/users`

```bash
npm i jsonwebtoken
```

```js
const jwt = require('jsonwebtoken');

const SECRET = process.env.JWT_SECRET || 'super-secret';

// Middleware
function requireAuth(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.sendStatus(401);
  const token = authHeader.split(' ')[1];
  jwt.verify(token, SECRET, (err, payload) => {
    if (err) return res.sendStatus(403);
    req.user = payload;
    next();
  });
}

app.get('/users', requireAuth, (req, res) => {
  // ...deliver user list, optionally filtered by role
});
```

### 3.5 Rate limiting (prevent brute‑force / DoS)

```bash
npm i express-rate-limit
```

```js
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 mins
  max: 100, // max 100 requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);
```

### 3.6 Logging & Monitoring

```bash
npm i morgan winston
```

```js
const morgan = require('morgan');
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'production' ? 'warn' : 'debug',
  transports: [new winston.transports.Console()],
});

app.use(morgan('combined', { stream: { write: msg => logger.info(msg.trim()) } }));
```

### 3.7 Error handling middleware

```js
// at the end of all route declarations
app.use((err, req, res, next) => {
  logger.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});
```

