// app.js
require('dotenv').config();        // 1) Load .env
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');

const app = express();
const PORT = process.env.PORT || 3000;

// --------------
//  Middleware
// --------------
app.set('trust proxy', true);     // For proper X-Forwarded-* handling

app.use(helmet());                // Security headers
app.use(cors({ origin: 'https://your-client.com' })); // Replace with real domain
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 200,
  standardHeaders: true,
  legacyHeaders: false,
}));
app.use(morgan('combined'));      // Logging
app.use(express.json());          // REST body parser

// --------------
//  Helpers
// --------------
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = typeof authHeader === 'string' && authHeader.startsWith('Bearer ')
      ? authHeader.slice(7)
      : null;
  if (!token) return res.sendStatus(401);
  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// --------------
//  Routes
// --------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {
  // In real life this would come from a DB
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example POST for demo of validation
app.post('/signup',
  [body('email').isEmail().normalizeEmail(),
   body('password').isLength({ min: 8 })],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty())
      return res.status(400).json({ errors: errors.array() });
    // ... create user logic
    res.status(201).json({ message: 'User created' });
  }
);

// --------------
//  Error handlers
// --------------
app.use((req, res, next) => {  // 404
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => { // General error
  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production' ? 'Internal Server Error' : err.message;
  console.error(err);
  res.status(status).json({ error: message });
});

// --------------
//  Start
// --------------
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

