```js
// ------ app.js (security‑reviewed) -------------
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');

const app = express();

// 1️⃣ Harden HTTP headers
app.use(helmet());

// 2️⃣ Rate‑limit API traffic
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,
    handler: (_, res) => {
      res.status(429).json({ error: 'Too many requests. Try again later.' });
    },
  })
);

// 3️⃣ Strict CORS policy
app.use(
  cors({
    origin: 'https://trusted.example.com',
    optionsSuccessStatus: 200,
  })
);

// 4️⃣ Simple JWT authentication middleware
const JWT_SECRET = process.env.JWT_SECRET || 'dev_secret';
function authenticate(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: 'Missing token' });

  const token = auth.split(' ')[1];
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    return next();
  } catch {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// 5️⃣ Health check – no auth required
app.get('/health', (_, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 6️⃣ Protected /users endpoint – returns only permitted fields
app.get('/users', authenticate, (_, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  const safeUsers = users.map((u) => ({ id: u.id, name: u.name }));
  res.json(safeUsers);
});

// 7️⃣ Logging (simplified)
app.use((req, res, next) => {
  // env variable called LOG_LEVEL can be 'info' or 'error'
  const lvl = process.env.LOG_LEVEL || 'info';
  console[lvl](`${req.method} ${req.originalUrl} from ${req.ip}`);
  next();
});

app.listen(3000, () => console.log('Server running on port 3000'));
module.exports = app;
```

> **Notice**:  
> * Production setups should replace `console.log` with a proper logger (Winston, Bunyan, etc).  
> * The `/auth/login` route, JWT issuance, and storing `JWT_SECRET` securely are omitted for brevity but are essential in a real deployment.  

