```js
// app.js
const express      = require('express');
const helmet       = require('helmet');
const cors         = require('cors');
const jwt          = require('jsonwebtoken');
const { expressjwt } = require('express-jwt');
const rateLimit    = require('express-rate-limit');
const Joi          = require('joi');
const winston      = require('winston');

const app          = express();
const JWT_SECRET   = process.env.JWT_SECRET || 'super-secret-key';

// ---------- Logging ----------
const logger = winston.createLogger({
  level: 'info',
  transports: [
    new winston.transports.Console({ format: winston.format.simple() })
  ]
});
app.use((req, res, next) => { logger.info(`${req.method} ${req.url}`); next(); });

// ---------- Security ----------
app.use(helmet());                       // HTTP headers
app.use(cors({ origin: 'https://myapp.example.com', methods: ['GET'] })); // adjust origin
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));

// ---------- Body parsing ----------
app.use(express.json());

// ---------- Auth ----------
app.use(
  expressjwt({ secret: JWT_SECRET, algorithms: ['HS256'] })
    .unless({ path: ['/health', '/auth/login'] })
);

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.post('/auth/login', (req, res) => {
  const { username, password } = req.body;
  // Replace with DB-backed check + proper hashing in prod
  if (username === 'admin' && password === 'password') {
    const token = jwt.sign({ sub: username, role: 'admin' }, JWT_SECRET, { expiresIn: '1h' });
    return res.json({ token });
  }
  return res.status(401).json({ error: 'Invalid credentials' });
});

app.post('/user', (req, res) => {
  const schema = Joi.object({
    name: Joi.string().max(30).required(),
    email: Joi.string().email().required()
  });

  const { error } = schema.validate(req.body);
  if (error) {
    return res.status(400).json({ error: error.details[0].message });
  }

  // Dummy response – real logic should persist to DB
  res.status(201).json({ message: 'User created', data: req.body });
});

// ---------- Error handling ----------
app.use((err, req, res, next) => {
  if (err.name === 'UnauthorizedError') {
    // JWT auth error
    logger.warn(`Auth error: ${err.message}`);
    return res.status(401).json({ error: 'Invalid token' });
  }
  logger.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------- Server ----------
app.listen(3000, () => {
  logger.info('Server running on port 3000');
});

module.exports = app;
```

