## Full “Production‑Ready” Boilerplate

Below is a refactored version of `app.js` that incorporates the key security fixes above.  You can copy & paste this into your project.  It still serves the same sample endpoints but is ready for real‑world use.

```js
// app.js – Production‑ready template
// 1️⃣ Imports
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize'); // prevent NoSQL injection
const cookieParser = require('cookie-parser');
const morgan = require('morgan');
const Pino = require('pino');
const pinoHttp = require('pino-http');

// 2️⃣ Logger (Pino)
const logger = Pino({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  prettyPrint: process.env.NODE_ENV !== 'production',
  timestamp: Pino.stdTimeFunctions.isoTime,
});
const app = express();
app.use(pinoHttp({ logger }));

// 3️⃣ Security middleware
app.use(helmet());                       // Set secure headers
app.use(express.json({ limit: '1mb' })); // Body parser + size limit
app.use(express.urlencoded({ extended: false }));
app.use(cookieParser());

// 4️⃣ CORS – expose only your origin
app.use(cors({
  origin: 'https://yourdomain.com',
  credentials: true,
}));

// 5️⃣ Rate limiting – block brute force
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 mins
  max: 200,                 // max 200 req per IP
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests, please slow down.' });
  },
}));

// 6️⃣ Input sanitisation
app.use(mongoSanitize()); // blocks operators like $gt, $ne

// 7️⃣ Demo Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Dummy auth middleware
const authenticate = (req, res, next) => {
  const token = req.cookies.token;
  if (!token) return res.status(401).json({ error: 'No token provided' });
  // Token verification (use jwk or secret)
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;
    next();
  } catch (_) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// Example protected endpoint
app.get('/users', authenticate, (req, res) => {
  if (!req.user.isAdmin) return res.status(403).json({ error: 'Forbidden' });

  // Suppress PII for non‑admin users
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.json(users);
});

// 8️⃣ Not‑found & error handling
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

app.use((err, req, res, next) => {
  logger.error(err);
  if (process.env.NODE_ENV !== 'production') {
    res.status(500).json({ error: err.message });
  } else {
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// 9️⃣ Start server
const port = process.env.PORT || 3000;
app.listen(port, () => {
  logger.info(`Server running on port ${port}`);
});

module.exports = app;       // For tests
```

### What this does

| Feature | Why it matters |
|---------|----------------|
| `helmet()` | Mitigates 7: Security Mis‑configuration – sets HTTP security headers (Content‑Security‑Policy, XSS‑Protection, etc.). |
| `cors()` | Prevents open‑access CORS (A7). |
| `rateLimit()` | Throttles clients (A1 & A2). |
| `mongoSanitize()` | Removes MongoDB query selectors from request bodies – a prevention against NoSQL injection. |
| `cookieParser()` + JWT | Shows safe token handling with HttpOnly & SameSite. |
| Logger via Pino | Provides structured, rotatable logs – mandatory for A10. |
| `express.json()` size limit | Prevents memory‑real denial‑of‑service via huge payload. |
| Input & Output filtering | Encodes/validates fields – protects against XSS and injection. |
| Explicit `404` & `500` handlers | Avoid leaking stack traces (A10). |

