```js
/* app.js – secure baseline */

const express = require('express');
const helmet  = require('helmet');
const cors    = require('cors');
const rateLimit = require('express-rate-limit');
const jwt     = require('jsonwebtoken');
const app = express();

// ---------- Middleware ----------
app.use(helmet());                      // Set secure HTTP headers
app.use(cors({ origin: false }));        // Disable CORS (adjust as needed)

// Rate limit global (adjust windowMs & max)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 200,
  standardHeaders: true,
  legacyHeaders: false
});
app.use(limiter);

// ---------- Auth utilities ----------
const AUTH_REQUIRED_ROLES = ['admin'];
function auth(req, res, next) {
  const token = req.header('Authorization')?.replace(/^Bearer\s+/i, '');
  if (!token) return res.sendStatus(401);
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;
    next();
  } catch (e) { return res.sendStatus(401); }
}
function requireRole(role) {
  return (req, res, next) => {
    if (!req.user || req.user.role !== role) return res.sendStatus(403);
    next();
  };
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users',
  auth,
  requireRole(AUTH_REQUIRED_ROLES[0]),   // only admins
  (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com'   }
    ]);
  });

/* ====================  Error handling ==================== */
app.use((err, req, res, next) => {
  console.error(err); // log error details
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ message: 'Internal Server Error' });
  }
  res.status(500).json({ error: err.message, stack: err.stack });
});

/* ====================  Server start ==================== */
const port = process.env.PORT ? parseInt(process.env.PORT, 10) : 3000;

if (require.main === module) {
  // In dev we just use http, in prod use https via a reverse proxy
  app.listen(port, () => {
    console.log(`Server running on port ${port}`);
  });
}

module.exports = app;
```

